        case 2:
            ruleForm.opcpList.map(iten => {
                iten.minShare = ruleForm.minShare
            })
            break
        case 3:
            ruleForm.opcpList.map(iten => {
                iten.maxShare = ruleForm.maxShare
            })
            break
        case 4:
