const confirmAmount = async(type) => {
    let that = this
    if (loading.value) {
        return false
    }
    loading.value = true
    setTimeout(() => {
        loading.value = false
    }, 3000)
    
    if (!dataParams.ops) {
        showToast({
            message: '请选择类型!',
