const getUserInfo = async() => {
    try {
        ruleForm.lotlist = []
        ruleForm.opcpList = []
        const res = await userStore.getQueryOrg(props.id)
        userInfo.value = res.data
        if (res.data.handicapList.length > 0) {
            for (let j = 0; j < res.data.handicapList.length; j++) {
                if (res.data.handicapList[j] == 1) {
                    isA.value = true
                }
                if (res.data.handicapList[j] == 2) {
                    isB.value = true
                }
                if (res.data.handicapList[j] == 3) {
                    isC.value = true
                }
                if (res.data.handicapList[j] == 4) {
                    isD.value = true
                }
            }
        }
        
        if (res.data.menuList) {
            for (let j = 0; j < res.data.menuList.length; j++) {
                if (res.data.menuList[j] == 1) {
                    ruleForm.isOpen = 1
                }
                if (res.data.menuList[j] == 2) {
                    ruleForm.finalOdds = 1
                }
                if (res.data.menuList[j] == 3) {
                    ruleForm.breakStatus = 1
                }
                if (res.data.menuList[j] == 11) {
                    ruleForm.money_odds = 1
                }
                if (res.data.menuList[j] == 12) {
                    ruleForm.member_odds = 1
                }
                if (res.data.menuList[j] == 13) {
                    ruleForm.auto_odds = 1
                }
                if (res.data.menuList[j] == 15) {
                    ruleForm.manual_odds = 1
                }
            }
        }
        
        let t2 = ''
        res.data.occupyList.map(iten => {
            if (iten.isChange == 1) {
                t2 = 1
            }
        })
        userInfo.value.isChange = t2
        ruleForm.opcpList = res.data.occupyList
        lotterylist.value = res.data.lotteryList1
        
        lotterylist.value.map(item => {
            res.data.lotteryList.map(its => {
                if (its.lotteryId == item.lotteryId) {
                    item.show = true
                }
            })
        })
        
        res.data.lotteryList.map(items => {
            ruleForm.lotlist.push(items.lotteryId)
            if (logInfo.value.role == 1) {
                ruleForm.opcpList.map(its => {
                    if (items.lotteryId == its.lotteryId) {
                        its.isNeed = items.isNeed
                    }
                })
            }
        })
        
        if (res.data.layer > 2) {
            let lots = res.data.pmenuList
            if (lots.length > 0) {
                for (let i = 0; i < lots.length; i++) {
                    if (lots[i] == 1) {
                        isIOpen.value = false
                    }
                }
            }
        }
        
        if (userInfo.value.layer == 3) {
            ruleForm.companyName = res.data.companyName
            ruleForm.name = res.data.nickName
        }
        
        ruleForm.nickName = res.data.nickName
        ruleForm.id = res.data.id
        ruleForm.status = res.data.status
        ruleForm.whiteIp = res.data.whiteIp
        
        let numlist = res.data.whiteIp ? res.data.whiteIp.split(',') : ''
        if (numlist.length > 0) {
            ruleForm.listIp = []
            numlist.map(its => {
                ruleForm.listIp.push({ ip: its })
            })
        }
        
        ruleForm.handicapList = res.data.handicapList
        ruleForm.isRelyOn = res.data.isRelyOn ? res.data.isRelyOn : 1
        ruleForm.mode = res.data.mode
    } catch (error) {
        console.error(error)
    }
}

const onSubmit = (formName) => {
    let that = this
    !ruleForm.passwd && (rules.passwd[0].required = false)
    if (ruleForm.passwd) {
        let paw = ruleForm.passwd.toLowerCase()
        let pass = md5(paw)
        ruleForm.password = pass
    }
    if (ruleForm.secound) {
        let paw1 = ruleForm.secound.toLowerCase()
        let sendpass = md5(paw1)
        ruleForm.secoundPassword = sendpass
    }
    if (userInfo.value.layer == 3) {
        if (ruleForm.companyName && ruleForm.name) {
            ruleForm.nickName = ruleForm.companyName + '_' + ruleForm.name
        } else {
            showToast({
                message: '昵称和分公司名称必须填写',
                className: 'custom-toast',
                duration: 1000  // 自定义显示时间
            });
            return false
        }
    }
    loading.value = true
    editProxy()
}

const editProxy = async() => {
    let that = this
    const loadingToast = showLoadingToast({
        lock: true,
        duration: 0,
        forbidClick: true,
        mask: true,
        background: 'rgba(0, 0, 0, 0.7)',
        message: '正在加载……'
    })
    
    ruleForm.occupyList = []
    ruleForm.menuList = []
    ruleForm.replenishOpen = []
    ruleForm.lotteryList = []
    
    lotterylist.value.map(item => {
        ruleForm.lotlist.map(items => {
            if (item.lotteryId == items) {
                ruleForm.lotteryList.push(item)
            }
        })
    })
    
    if (ruleForm.isOpen == 1) {
        ruleForm.menuList.push(1)
    }
    
    if (userInfo.value.layer == 3 && userInfo.value.role == 3) {
        if (ruleForm.finalOdds == 1) {
            ruleForm.menuList.push(2)
        }
        if (ruleForm.breakStatus == 1) {
            ruleForm.menuList.push(3)
        }
        if (ruleForm.auto_odds == 1) {
            ruleForm.menuList.push(13)
        }
        if (ruleForm.manual_odds == 1) {
            ruleForm.menuList.push(15)
        }
        if (ruleForm.money_odds == 1) {
            ruleForm.menuList.push(11)
        }
        if (ruleForm.member_odds == 1) {
            ruleForm.menuList.push(12)
        }
    }
    
    let t = ''
    ruleForm.opcpList.map(iten => {
        if (iten.repFlag == 1) {
            ruleForm.replenishOpen.push(iten.lotteryId)
        }
        if (iten.maxOccupy < iten.pminShare || iten.maxOccupy > iten.pmaxShare || iten.minShare > iten.maxShare || iten.minShare > iten.pmaxShare || iten.maxShare > iten.pmaxShare) {
            t = 1
            return false
        }
    })
    
    if (t) {
        showToast({
            message: '上级占成不能超过最大值或者最低值不能超过最高值',
            className: 'custom-toast',
            duration: 2000  // 自定义显示时间
        });
        return false
    }
    
    ruleForm.occupyList = ruleForm.opcpList
    
    let ips = ''
    ruleForm.listIp.map(its => {
        if (its.ip) {
            ips += its.ip + ','
        }
    })
    if (ips) {
        ips = ips.substring(0, ips.length - 1)
    }
    ruleForm.whiteIp = ips
    
    setTimeout(function () {
        loadingToast.close()
    }, 5000)
    try {
        const res = await userStore.orgUpdate(ruleForm)
        loading.value = false
        loadingToast.close()
        showToast({
            message: '修改成功',
            className: 'custom-toast',
            duration: 2000  // 自定义显示时间
        });
        if (res.code == 200) {
            router.push({ name: 'UserManage', params: { pid: userInfo.value.pid } })
        }
    } catch (error) {
        console.log('修改失败')
    }
}

const cancelForm = () => {
    router.push({ name: 'UserManage', params: { pid: userInfo.value.pid } })
}

// ==================== 生命周期 ====================
onMounted(() => {
    let ust = JSON.parse(localStorage.getItem('userInfo'))
    logInfo.value = ust
    getUserInfo()
})
